import os, sqlite3, tempfile, sys, time, multiprocessing as mp
sys.path.insert(0, "src")
from forgetting_evidence.requests import RequestStore

def worker(db, rid, role, outq):
    try:
        s = RequestStore(db)
        if role == "reconcile":
            for _ in range(50):
                s.reconcile_execution("t", rid)
        elif role == "batch":
            cur = None
            for _ in range(50):
                p = s.reconcile_batch("t", cur, limit=5)
                cur = p["next_cursor"]
                if p["finished"]:
                    cur = None
        elif role == "claim":
            for _ in range(50):
                c = s.claim_next("t", "w", 1)
                if c is not None and c["request_id"] == rid:
                    try:
                        s.finish_claim("t", rid, c["claim_token"], "completed")
                    except Exception:
                        pass
                time.sleep(0.001)
        outq.put(("ok", role))
    except Exception as e:
        outq.put(("ERR", role, type(e).__name__, str(e)))

if __name__ == "__main__":
    tmp = tempfile.mkdtemp(); db = os.path.join(tmp, "e.db")
    s = RequestStore(db)
    rid = s.submit("t", "subj", ["email"], "k")["request_id"]
    s.claim_next("t", "w", 1)
    time.sleep(1.2)
    ctx = mp.get_context("fork")
    q = ctx.Queue()
    procs = []
    for role in ["reconcile"]*3 + ["batch"]*2 + ["claim"]*3:
        p = ctx.Process(target=worker, args=(db, rid, role, q)); p.start(); procs.append(p)
    errs = []
    for _ in procs:
        msg = q.get(timeout=120)
        if msg[0] == "ERR": errs.append(msg)
    for p in procs: p.join()
    print("ERRORS LEAKED:", errs)
    # invariants
    s2 = RequestStore(db)
    st = s2.get_status("t", rid)["status"]
    audit = [e["status"] for e in s2.audit("t", rid)]
    finals = [x for x in audit if x in ("completed","failed")]
    print("final status:", st, "audit:", audit, "num terminal events:", len(finals))
    print("verify:", s2.verify_evidence("t", rid))
    with sqlite3.connect(db) as raw:
        print("tokens:", raw.execute("SELECT count(*) FROM claim_tokens").fetchone()[0])
        print("terminal attempts:", raw.execute("SELECT attempt_number, result FROM claim_attempts").fetchall())
