import os, sqlite3, tempfile, sys, time, random
sys.path.insert(0, "src")
from forgetting_evidence.requests import RequestStore

def types_ok(o, path="$"):
    if o is None or isinstance(o, str) or isinstance(o, bool) or isinstance(o, int):
        return True
    if isinstance(o, float):
        return False
    if isinstance(o, list):
        return all(types_ok(x, path) for x in o)
    if isinstance(o, dict):
        return all(types_ok(v, path) for v in o.values())
    return False

def run(seed):
    random.seed(seed)
    tmp = tempfile.mkdtemp(); db = os.path.join(tmp,"e.db")
    s = RequestStore(db)
    reqs=[]
    for i in range(random.randint(1,5)):
        reqs.append(s.submit("t",f"s{i}",["email"],f"k{i}")["request_id"])
        time.sleep(0.0011)
    live_tokens = {}  # rid -> token
    def expire_all():
        with sqlite3.connect(db) as r:
            r.execute("UPDATE claim_attempts SET lease_expires_at='2020-01-01T00:00:00.000000Z'")
            r.commit()
    for step in range(50):
        op = random.random()
        try:
            if op < 0.22:
                c = s.claim_next("t", f"w{random.randint(0,2)}", random.choice([1,1,3600]))
                if c: live_tokens[c["request_id"]] = c["claim_token"]
            elif op < 0.34:
                expire_all()
                time.sleep(0.002)
            elif op < 0.46:
                rid = random.choice(reqs); s.reconcile_execution("t", rid)
            elif op < 0.62:
                p = s.reconcile_batch("t", limit=random.choice([1,2,5]))
                assert types_ok(p), (seed, step, "FLOAT in batch", p)
                assert set(p) == {"batch_id","next_cursor","finished","items"}
                assert isinstance(p["batch_id"], str) and p["batch_id"]
                assert p["next_cursor"] is None or isinstance(p["next_cursor"], str)
                assert isinstance(p["finished"], bool)
                assert isinstance(p["items"], list)
                for it in p["items"]:
                    assert set(it)=={"request_id","status"}
                    assert isinstance(it["request_id"], str) and isinstance(it["status"], str)
            elif op < 0.72:
                # finish a live token
                if live_tokens:
                    rid = random.choice(list(live_tokens))
                    tok = live_tokens.pop(rid)
                    try: s.finish_claim("t", rid, tok, random.choice(["completed","failed"]))
                    except Exception: live_tokens[rid]=tok
            elif op < 0.8:
                s = RequestStore(db)
            else:
                # single reconcile type check
                rid=random.choice(reqs)
                rec=s.reconcile_execution("t",rid)
                assert set(rec)=={"request_id","status","created_at"}
                assert all(isinstance(v,str) for v in rec.values())
        except AssertionError: raise
        except Exception as e:
            print(seed, step, "UNEXPECTED", type(e).__name__, e); return False
        # invariant: terminal request => exactly one terminal event & no open attempt & no token
        with sqlite3.connect(db) as r:
            for rid in reqs:
                status = r.execute("SELECT status FROM requests WHERE request_id=?", (rid,)).fetchone()[0]
                opens = r.execute("SELECT count(*) FROM claim_attempts WHERE request_id=? AND result IS NULL", (rid,)).fetchone()[0]
                terms = r.execute("SELECT count(*) FROM status_events WHERE request_id=? AND status IN ('completed','failed')", (rid,)).fetchone()[0]
                toks = r.execute("SELECT count(*) FROM claim_tokens WHERE request_id=?", (rid,)).fetchone()[0]
                if status in ("completed","failed"):
                    if opens != 0:
                        print(seed, step, "terminal has open attempt", rid, status); return False
                    if terms != 1:
                        print(seed, step, "terminal events != 1", rid, terms); return False
                    if toks != 0:
                        print(seed, step, "terminal has token", rid); return False
    return True

fails=0
for seed in range(400):
    if not run(seed):
        fails+=1
        if fails>4: break
print("done fails:", fails)
